/* SPDX-License-Identifier: GPL-3.0-or-later
 *
 * slugify() from python-slugify with its default arguments, which the
 * upstream UI uses to name the rules it creates
 * (ui/opensnitch/dialogs/prompt/_utils.py). The transliteration tables
 * (unidecode, NFKD, HTML entities) are generated by tools/gen-slug-tables.py
 * and cover Latin, general punctuation and currency symbols; other
 * characters become a separator (docs/UPSTREAM.md, divergences).
 *
 * Copyright (C) 2026 the Kisnitch contributors.
 *
 * Memory: returned strings are malloc'd and owned by the caller.
 */
#ifndef KS_UI_SLUG_H
#define KS_UI_SLUG_H

/* slugify(text). `text` is UTF-8 (invalid sequences count as U+FFFD).
 * NULL on OOM. */
char *ks_slugify(const char *text);

#endif
